arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Fixed: Use scoped lifetime to avoid capturing a scoped service in a singleton
// (.NET 9 enables ValidateScopes in development, which catches captive dependencies)
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
// Fixed: .NET 9 HttpClientFactory uses SocketsHttpHandler by default;
// casting to HttpClientHandler throws InvalidCastException
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });
// Fixed: .NET 9 Forwarded Headers Middleware ignores X-Forwarded-* from unknown proxies.
// Configure KnownProxies or KnownNetworks for your environment.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    options.KnownNetworks.Clear();
    options.KnownProxies.Clear();
});
// Fixed: .NET 9 HttpClientFactory redacts all header values in Trace-level logs by default.
// Allowlist specific non-sensitive headers you need for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id" && h != "X-Correlation-Id" && h != "Content-Type" && h != "Accept"));
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

